mapper.update:
UPDATE feedback_settings
SET enabled = #{enabled}, frequency_days = #{frequencyDays}, updated_at = #{now}, updated_by = #{staffId}
WHERE id = 1

mapper.select:
UPDATE feedback_requests SET sent_at = #{now}
WHERE id IN (SELECT id FROM feedback_requests
             WHERE sent_at IS NULL AND due_at <= #{now} AND expires_at > #{now}
             ORDER BY due_at LIMIT #{limit} FOR UPDATE SKIP LOCKED)
RETURNING customer_id

mapper.insert:
INSERT INTO feedback (id, request_id, customer_id, branch_id, rating, reasons, comment, created_at)
SELECT #{id}, r.id, r.customer_id, r.branch_id, #{rating}, #{reasons}, #{comment}, #{now}
FROM feedback_requests r
WHERE r.id = #{requestId} AND r.customer_id = #{customerId} AND r.expires_at > #{now}
  AND r.sent_at IS NOT NULL
ON CONFLICT (request_id) DO NOTHING

mapper.select:
SELECT
    (SELECT count(*) FROM feedback f WHERE f.created_at >= #{since} AND f.created_at < #{until}
        AND f.rating = 'GOOD' AND f.branch_id = #{branchId}) AS good,
    (SELECT count(*) FROM feedback f WHERE f.created_at >= #{since} AND f.created_at < #{until}
        AND f.rating = 'OK' AND f.branch_id = #{branchId}) AS ok,
    (SELECT count(*) FROM feedback f WHERE f.created_at >= #{since} AND f.created_at < #{until}
        AND f.rating = 'BAD' AND f.branch_id = #{branchId}) AS bad,
    (SELECT count(*) FROM feedback_requests r WHERE r.sent_at >= #{since} AND r.sent_at < #{until}
        AND r.branch_id = #{branchId}) AS sent,
    (SELECT count(*) FROM feedback f WHERE f.rating = 'BAD' AND f.resolved_at IS NULL
        AND f.branch_id = #{branchId}) AS unresolved_bad
